export function c024(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 12 * millimeter });
    const toolSketch = newSketchOnPlane(context, id + "toolSketch", { "sketchPlane" : plane(vector(0, 0, -5) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(toolSketch, "circle1", { "center" : vector(40, 30) * millimeter, "radius" : 10 * millimeter });
    skSolve(toolSketch);
    extrude(context, id + "tool", { "entities" : qSketchRegion(id + "toolSketch"), "endBound" : BoundingType.BLIND, "depth" : 25 * millimeter });
    splitPart(context, id + "split1", { "splitType" : SplitType.FACE, "faceTargets" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 12) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(40, 15, 6) * millimeter)]), "faceTools" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "tool", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(30, 30, 5) * millimeter), "keepToolSurfaces" : true });
}

// transform: a block scaled differently along each axis about a corner
export function c025(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(20, 10) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 5 * millimeter });
    transform(context, id + "scale1", { "entities" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "transformType" : TransformType.SCALE_UNIFORMLY, "uniform" : false, "scaleX" : 2, "scaleY" : 0.5, "scaleZ" : 3, "scalePoint" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(0, 0, 0) * millimeter), "makeCopy" : false, "oppositeDirectionEntity" : false });
}

// isocline: a sphere split at 30 degrees from up
export function c026(context is Context, id is Id)
{
    fSphere(context, id + "base", { "radius" : 10 * millimeter });
    const up = newSketchOnPlane(context, id + "up", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(up, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(up);
    isocline(context, id + "iso1", { "faces" : qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), "direction" : qCreatedBy(id + "up", EntityType.EDGE), "oppositeDirection" : false, "angle" : 30 * degree, "split" : true });
}

// isocline: the 20 degree isoclines of a torus-like revolve, as curves
export function c027(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skCircle(s1, "circle1", { "center" : vector(20, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(s1);
    const axis1 = newSketchOnPlane(context, id + "axis1", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis1, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis1);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "s1"), "axis" : qCreatedBy(id + "axis1", EntityType.EDGE), "angle" : 360 * degree });
    const up = newSketchOnPlane(context, id + "up", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(up, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(up);
    isocline(context, id + "iso1", { "faces" : qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), "direction" : qCreatedBy(id + "up", EntityType.EDGE), "oppositeDirection" : false, "angle" : 20 * degree, "split" : false });
}
